const { executeQuery } = require('./backend/config/database');

async function testLeaveBalanceQuery() {
  try {
    console.log('🔍 Testing leave balance query...');
    
    // Test the exact query that should be generated by AI
    const query = `
      SELECT lb.*, lt.name as leave_type_name
      FROM leave_balances lb
      JOIN leave_types lt ON lb.leave_type_id = lt.id
      WHERE lb.employee_id = ? AND lb.year = YEAR(CURDATE())
    `;
    
    // Test with employee ID 1 (assuming this exists)
    const employeeId = 1;
    console.log(`📋 Executing query for employee ID: ${employeeId}`);
    console.log(`📋 Query: ${query}`);
    
    const results = await executeQuery(query, [employeeId]);
    
    console.log(`✅ Query returned ${results.length} records`);
    
    if (results.length > 0) {
      console.log('📊 Sample result:');
      console.log(JSON.stringify(results[0], null, 2));
      
      console.log('\n📋 All leave types found:');
      results.forEach((result, index) => {
        console.log(`${index + 1}. ${result.leave_type_name}: ${result.remaining_days} days remaining`);
      });
    } else {
      console.log('❌ No leave balance records found');
      
      // Check if employee exists
      const empCheck = await executeQuery('SELECT id, first_name, last_name FROM employees WHERE id = ?', [employeeId]);
      console.log(`👤 Employee check: ${empCheck.length > 0 ? 'EXISTS' : 'NOT FOUND'}`);
      
      // Check leave types
      const leaveTypesCheck = await executeQuery('SELECT * FROM leave_types WHERE is_active = 1');
      console.log(`📝 Active leave types: ${leaveTypesCheck.length}`);
      leaveTypesCheck.forEach(lt => {
        console.log(`  - ${lt.name} (ID: ${lt.id})`);
      });
      
      // Check leave balances for any employee
      const anyBalances = await executeQuery('SELECT COUNT(*) as count FROM leave_balances WHERE year = YEAR(CURDATE())');
      console.log(`📊 Total leave balances for current year: ${anyBalances[0].count}`);
    }
    
  } catch (error) {
    console.error('❌ Test failed:', error);
  }
}

testLeaveBalanceQuery();
